package ktanesolver.module.modded.regular.valves;import java.util.*;import org.springframework.stereotype.Service;import ktanesolver.annotation.ModuleInfo;import ktanesolver.dto.ModuleCatalogDto;import ktanesolver.entity.*;import ktanesolver.enums.ModuleType;import ktanesolver.logic.*;
@Service@ModuleInfo(type=ModuleType.VALVES,id="valves",name="Valves",category=ModuleCatalogDto.ModuleCategory.MODDED_REGULAR,description="Walk the serial-number combination table and apply material/color toggles.",tags={"valves","serial-number","binary","timer"})
public class ValvesSolver extends AbstractModuleSolver<ValvesInput,ValvesOutput>{static final List<String>TABLE=List.of("110","111","001","000","100","000","001","011","010","110","011","100","001","011","100","000","110","111","011","111","110","010","100","000","010","011","010","110","001","111","000","001","111","010","101","110");@Override protected SolveResult<ValvesOutput>doSolve(RoundEntity round,BombEntity bomb,ModuleEntity module,ValvesInput input){if(input==null||input.material()==null||input.blackValves()==null||input.blackValves().size()!=3||input.blackValves().stream().anyMatch(Objects::isNull))return failure("Enter the material and all three valve colors");String serial=bomb.getSerialNumber()==null?"":bomb.getSerialNumber().toUpperCase(Locale.ROOT);if(serial.length()!=6||!serial.matches("[A-Z0-9]{6}"))return failure("Bomb serial must contain six letters/digits");int sum=serial.chars().filter(Character::isDigit).map(c->c-'0').sum();boolean zero=sum==0;String target=zero?"101":walk(serial,sum),answer=target;if(!zero){if(input.material()==ValvesInput.Material.SILVER)answer=invert(answer);char[]bits=answer.toCharArray();for(int i=0;i<3;i++)if(input.blackValves().get(i))bits[i]=bits[i]=='1'?'0':'1';answer=new String(bits);}List<Integer>presses=new ArrayList<>();for(int i=0;i<3;i++)if(answer.charAt(i)=='1')presses.add(i+1);List<Integer>twitch=presses.isEmpty()?List.of(1,1):List.copyOf(presses);String initial=input.blackValves().stream().map(b->b?"1":"0").reduce("",String::concat);storeState(module,"valvesInitialState",initial);return success(new ValvesOutput(target,answer,List.copyOf(presses),twitch,zero));}
	static String walk(String serial,int sum){if(sum<1||sum>36)throw new IllegalArgumentException("Serial digit sum is outside the table");int index=sum-1;String current=TABLE.get(index);for(char c:serial.toCharArray()){boolean letter=Character.isLetter(c);int move=letter?(c-'A'+1)%10:-(c-'0');index=Math.floorMod(index+move,36);int matches=matches(current,TABLE.get(index));while(matches==0){index=Math.floorMod(index+(letter?1:-1),36);matches=matches(current,TABLE.get(index));}if(matches==3)return current;int flip;if(matches==1){flip=0;while(current.charAt(flip)!=TABLE.get(index).charAt(flip))flip++;}else{flip=0;while(current.charAt(flip)==TABLE.get(index).charAt(flip))flip++;}char[]bits=current.toCharArray();bits[flip]=bits[flip]=='1'?'0':'1';current=new String(bits);}return current;}
	private static int matches(String a,String b){int n=0;for(int i=0;i<3;i++)if(a.charAt(i)==b.charAt(i))n++;return n;}private static String invert(String s){return s.chars().mapToObj(c->c=='1'?"0":"1").reduce("",String::concat);}}
